package org.sleepwell.app;
import android.app.*;import android.content.*;import android.os.*;import android.view.*;import android.widget.*;

/** Explicit voice-activity challenge; no capture on launch, permission return or recreation. */
public final class SpeakChallengeActivity extends Activity {
    static final int FALLBACK=4;private String run,request;private int unit;volatile boolean foreground;private boolean resumed,returned,attemptActive;private SpeakAccess.Factory access;private SpeakAccess.Operation operation;private final Handler main=new Handler(Looper.getMainLooper());private final Runnable changed=this::render;private String issue="",shown="";
    @Override public void onCreate(Bundle saved){super.onCreate(saved);setShowWhenLocked(true);getWindow().addFlags(WindowManager.LayoutParams.FLAG_KEEP_SCREEN_ON);RecordUi.review(this);run=getIntent().getStringExtra("run");request=getIntent().getStringExtra("request");unit=getIntent().getIntExtra("unit",-1);access=SpeakAccess.factory;try{if(request==null||!java.util.UUID.fromString(request).toString().equals(request)||!access.current(this,run,unit)){finish();return;}}catch(RuntimeException invalid){finish();return;}operation=access.existing(run,unit,changed);render();}
    boolean admission(){return foreground&&resumed&&hasWindowFocus()&&!isFinishing()&&!isDestroyed()&&access!=null&&access.current(this,run,unit);}
    private String signature(){return (operation==null?"IDLE":operation.state()+":"+operation.error()+":"+operation.accepted())+":"+access.permission(this)+":"+access.unavailable(this)+":"+issue;}
    private void render(){if(isDestroyed()||isFinishing()||access==null)return;if(!access.current(this,run,unit)){finish();return;}if(operation!=null&&operation.state()==SpeakRuntime.State.DONE&&operation.released()&&attemptActive&&admission()){result(RESULT_OK);return;}shown=signature();LinearLayout body=Design.page(this,false,null,null);RecordUi.label(this,body);RecordUi.header(body,"Speak challenge",this::finish);Design.space(body,20);Design.text(body,"Speak for about 2 seconds",25,600,Design.INK);Design.space(body,10);Design.text(body,"Detects speech sounds, not words or who is speaking. No recording is saved.",14,400,Design.MUTED);Design.space(body,20);
        SpeakRuntime.State state=operation==null?SpeakRuntime.State.IDLE:operation.state();String status=switch(state){case IDLE->"Ready when you are";case QUIETING->"Waiting for alarm sound to stop…";case LISTENING->"Listening · "+operation.accepted()+" of 2 speech windows";case CLOSING->"Stopping microphone…";case BLOCKED->"Microphone cleanup needs attention";case DONE->attemptActive?"Speech detected":"Previous attempt ended. Listen again.";case ERROR,CANCELLED->operation.error().isEmpty()?"Listening stopped":operation.error();};LinearLayout panel=Design.col(this);Design.pad(panel,18,20);panel.setBackground(Design.shape(this,Design.SOFT,18));Design.text(panel,status,17,600,Design.BROWN).setContentDescription("Speak status");body.addView(panel);Design.space(body,18);SpeakAccess.Permission permission=access.permission(this);boolean busy=operation!=null&&!operation.released();String unavailable=access.unavailable(this);if(!issue.isEmpty())Design.text(body,issue,13,500,0xffa93919);else if(!busy&&!unavailable.isEmpty())Design.text(body,unavailable,13,500,Design.MUTED);
        if(permission!=SpeakAccess.Permission.ALLOWED)Design.button(body,permission==SpeakAccess.Permission.SETTINGS?"Open microphone settings":"Allow microphone",false,()->{try{access.request(this);}catch(RuntimeException failure){issue="Microphone settings could not open. Use Math.";render();}});
        if(state==SpeakRuntime.State.BLOCKED)Design.button(body,"Retry microphone cleanup",true,()->operation.retry());else if(busy)Design.button(body,"Stop listening",false,()->operation.cancel());else{Button listen=Design.button(body,"Listen for speech",true,()->{if(!admission())return;issue="";attemptActive=true;try{operation=access.begin(this,run,unit,changed);}catch(RuntimeException failure){issue=failure.getMessage()==null?"Listening unavailable. Use Math.":failure.getMessage();}render();});RecordUi.enabled(listen,permission==SpeakAccess.Permission.ALLOWED&&unavailable.isEmpty());}
        Design.space(body,10);Button fallback=Design.button(body,"Use Math instead",false,()->{if(!admission())return;if(operation!=null&&!operation.released()){operation.cancel();issue="Wait for microphone cleanup before switching.";render();return;}result(FALLBACK);});RecordUi.enabled(fallback,!busy);Design.space(body,12);Design.text(body,"Alarm sound pauses only for this listening attempt. Vibration and lights keep their settings.",12,400,Design.MUTED);
    }
    private void result(int result){if(returned||!admission())return;returned=true;setResult(result,new Intent().putExtra("run",run).putExtra("unit",unit).putExtra("request",request));finish();}
    private final Runnable poll=new Runnable(){public void run(){if(!resumed||access==null)return;if(!access.current(SpeakChallengeActivity.this,run,unit)||!shown.equals(signature())||operation!=null&&attemptActive&&operation.state()==SpeakRuntime.State.DONE)render();main.postDelayed(this,200);}};
    @Override protected void onResume(){super.onResume();resumed=true;foreground=hasWindowFocus();main.post(poll);}
    @Override public void onWindowFocusChanged(boolean focus){super.onWindowFocusChanged(focus);foreground=resumed&&focus;if(focus){RecordUi.lightBars(this);if(access!=null)render();}else{attemptActive=false;if(operation!=null&&!operation.released())operation.cancel();}}
    @Override protected void onPause(){attemptActive=false;foreground=false;resumed=false;main.removeCallbacksAndMessages(null);if(operation!=null&&!operation.released())operation.cancel();super.onPause();}
    @Override protected void onDestroy(){foreground=false;main.removeCallbacksAndMessages(null);if(operation!=null&&!operation.released())operation.cancel();super.onDestroy();}
    @Override public void onRequestPermissionsResult(int request,String[] permissions,int[] grants){super.onRequestPermissionsResult(request,permissions,grants);if(request==SpeakAccess.PERMISSION)render();}
}
